csvline.reference:
"""Minimal CSV line splitting for vendor imports."""


def split_line(line: str) -> list[str]:
    """Split one CSV line into fields (double quotes may wrap a field)."""
    fields, cur, i, quoted = [], [], 0, False
    while i < len(line):
        ch = line[i]
        if quoted:
            if ch == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    cur.append('"')
                    i += 1
                else:
                    quoted = False
            else:
                cur.append(ch)
        elif ch == '"':
            quoted = True
        elif ch == ",":
            fields.append("".join(cur))
            cur = []
        else:
            cur.append(ch)
        i += 1
    if quoted:
        raise ValueError(f"unterminated quote: {line!r}")
    fields.append("".join(cur))
    return fields

